number.script:
          function updateStrength()
            local nBase = tonumber(self.getValue()) or 10;
            local nPoints = tonumber(window.points_strength.getValue()) or 0;
            local nRace = tonumber(window.race_strength.getValue()) or 0;
            local nBoosts = tonumber(window.boosts_strength.getValue()) or 0;            
            local nTotal = nBase + nRace + nPoints + nBoosts;

            local nItemBonus = tonumber(window.itembonus_strength.getValue()) or 0;
            nTotal = nTotal + nItemBonus;

            window.strength.setValue(nTotal);
          end
          function onValueChanged()
            updateStrength();
          end

function onValueChanged()
  local nPoints = tonumber(self.getValue()) or 0;
  if sf.isGt(0,nPoints) then
    self.setValue(0);
  elseif sf.isGt(nPoints,10) then
    self.setValue(10);
  end
  window.base_strength.updateStrength();
  window.points_total.update();
end

buttoncontrol.script:
function onButtonPress()
  local nSize = window.points_strength.getValue();
  nSize = nSize -1;
  if sf.isGt(0,nSize) then 
    nSize = 0;
  end
  window.points_strength.setValue(nSize);
end

function onButtonPress()
  local nSize = window.points_strength.getValue();
  nSize = nSize +1;
  if sf.isGt(nSize,10) then 
    nSize = 10;
  end
  window.points_strength.setValue(nSize);
end

function onButtonPress()
  local nSize = window.boosts_strength.getValue();
  nSize = nSize -1;
  if sf.isGt(0,nSize) then 
    nSize = 0;
  end
  window.boosts_strength.setValue(nSize);
end

function onButtonPress()
  local nSize = window.boosts_strength.getValue();
  nSize = nSize +1;
  if sf.isGt(nSize,5) then 
    nSize = 5;
  end
  window.boosts_strength.setValue(nSize);
end

