number.script:
function update()
  local nPoints = 0;
  nPoints = nPoints + (tonumber(window.points_strength.getValue()) or 0);
  nPoints = nPoints + (tonumber(window.points_dexterity.getValue()) or 0);
  nPoints = nPoints + (tonumber(window.points_constitution.getValue()) or 0);
  nPoints = nPoints + (tonumber(window.points_intelligence.getValue()) or 0);
  nPoints = nPoints + (tonumber(window.points_wisdom.getValue()) or 0);
  nPoints = nPoints + (tonumber(window.points_charisma.getValue()) or 0);
  self.setValue(nPoints);
  if sf.isGt(nPoints,10) then
    self.setColor("ff0000");
  else
    self.setColor("");
  end
end

buttoncontrol.script:
				function onButtonPress()
        	window.close();
				end
